ignoreCommand:
if ! cd ..; then echo "cannot reach outside Root Directory -- building (fail-closed)"; exit 1; fi;
if ! git rev-parse --is-inside-work-tree >/dev/null 2>&1; then echo "no git context outside Root Directory -- building (fail-closed)"; exit 1; fi;
BASE="${VERCEL_GIT_PREVIOUS_SHA:-}";
if [ -z "$BASE" ] || ! git cat-file -e "$BASE" 2>/dev/null; then echo "no usable previous-deploy commit (new branch / shallow depth=10) -- building (fail-closed)"; exit 1; fi;
if git diff --quiet "$BASE" HEAD -- . ':(exclude)docs/**' ':(exclude)README.md' ':(exclude)README_ja.md' ':(exclude)CHANGELOG.md' ':(exclude)AGENTS.md' ':(exclude)CLAUDE.md' ':(exclude)LICENSE'; then echo "docs-only diff -- skipping build"; exit 0; else echo "non-docs diff -- building"; exit 1; fi
